import 'package:mad_flutter_practicum/domain/domain.dart';

import '../news_list/widgets/news_card.dart';
import '../currency_list/widgets/currency_card.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  Future<void>? _syncFuture;

  List<CurrencyModel> _currencies = [];
  List<NewsModel> _news = [];

  @override
  void initState() {
    super.initState();
    _syncFuture = _loadData();
  }

  Future<void> _loadData() async {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    await Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) {
        setState(() => _currencies = page.items);
        return currencyRepository.saveCurrencyList(page.items);
      }),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((List<NewsModel> value) {
        setState(() => _news = value);
      }),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(title: Text(loc.dashboard)),
      body: FutureBuilder<void>(
        future: _syncFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting && _currencies.isEmpty && _news.isEmpty) {
            return const Center(child: CircularProgressIndicator());
          }

          final List<Widget> children = <Widget>[];

          if (_currencies.isNotEmpty) {
            children.addAll(<Widget>[
              Padding(
